    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Data-forward, professional aesthetic
           =========================================== */
        :root {
            --bg-primary: #0d1117;
            --bg-secondary: #161b22;
            --bg-tertiary: #21262d;
            --text-primary: #e6edf3;
            --text-secondary: #8b949e;
            --text-muted: #6e7681;
            --accent: #58a6ff;
            --accent-secondary: #3fb950;
            --accent-warning: #d29922;
            --accent-danger: #f85149;
            --border: #30363d;
            --glow: rgba(88, 166, 255, 0.15);

            --font-display: 'Space Grotesk', sans-serif;
            --font-mono: 'JetBrains Mono', monospace;
            --title-size: clamp(1.8rem, 5vw, 3.5rem);
            --h2-size: clamp(1.4rem, 3.5vw, 2.2rem);
            --h3-size: clamp(1rem, 2vw, 1.4rem);
            --body-size: clamp(0.8rem, 1.5vw, 1.1rem);
            --small-size: clamp(0.65rem, 1vw, 0.85rem);

            --slide-padding: clamp(1.5rem, 5vw, 5rem);
            --content-gap: clamp(0.8rem, 2vw, 1.5rem);
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-display);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.5;
            overflow-x: hidden;
        }

        /* ===========================================
           SLIDE BASE STYLES (from viewport-base.css)
           =========================================== */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1 {
            font-size: var(--title-size);
            font-weight: 700;
            line-height: 1.1;
            letter-spacing: -0.02em;
        }

        h2 {
            font-size: var(--h2-size);
            font-weight: 600;
            line-height: 1.2;
            margin-bottom: var(--content-gap);
        }

        h3 {
            font-size: var(--h3-size);
            font-weight: 500;
            color: var(--text-secondary);
        }

        p {
            font-size: var(--body-size);
            color: var(--text-secondary);
        }

        .mono {
            font-family: var(--font-mono);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
        .reveal:nth-child(3) { transition-delay: 0.3s; }
        .reveal:nth-child(4) { transition-delay: 0.4s; }
        .reveal:nth-child(5) { transition-delay: 0.5s; }
        .reveal:nth-child(6) { transition-delay: 0.6s; }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           SLIDE 1: TITLE
           =========================================== */
        .title-slide {
            background:
                radial-gradient(ellipse at 30% 20%, rgba(88, 166, 255, 0.12) 0%, transparent 50%),
                radial-gradient(ellipse at 70% 80%, rgba(63, 185, 80, 0.08) 0%, transparent 50%),
                var(--bg-primary);
        }

        .title-slide .slide-content {
            align-items: center;
            text-align: center;
        }

        .title-slide h1 {
            max-width: 90vw;
            margin-bottom: var(--content-gap);
        }

        .title-slide .subtitle {
            font-size: clamp(1rem, 2vw, 1.4rem);
            color: var(--text-secondary);
            max-width: 70ch;
            margin-bottom: var(--content-gap);
        }

        .title-slide .meta {
            display: flex;
            gap: clamp(1rem, 3vw, 2rem);
            font-size: var(--small-size);
            color: var(--text-muted);
        }

        .title-slide .meta span {
            display: flex;
            align-items: center;
            gap: 0.5em;
        }

        .badge {
            display: inline-block;
            padding: 0.3em 0.8em;
            background: var(--bg-tertiary);
            border: 1px solid var(--border);
            border-radius: 4px;
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .badge-accent {
            background: rgba(88, 166, 255, 0.15);
            border-color: var(--accent);
            color: var(--accent);
        }

        /* ===========================================
           SLIDE 2: INTELLIGENCE INDEX TABLE
           =========================================== */
        .data-slide {
            background: var(--bg-primary);
        }

        .slide-header {
            margin-bottom: clamp(1rem, 3vh, 2rem);
        }

        .slide-header .highlight {
            color: var(--accent);
        }

        .data-table {
            width: 100%;
            max-width: 900px;
            border-collapse: collapse;
            font-size: var(--small-size);
        }

        .data-table th {
            text-align: left;
            padding: 0.6em 1em;
            background: var(--bg-tertiary);
            border-bottom: 2px solid var(--border);
            font-weight: 600;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            font-size: calc(var(--small-size) * 0.9);
        }

        .data-table td {
            padding: 0.5em 1em;
            border-bottom: 1px solid var(--border);
            vertical-align: middle;
        }

        .data-table tr:hover td {
            background: var(--bg-secondary);
        }

        .data-table .rank {
            font-weight: 700;
            color: var(--accent);
            width: 3em;
        }

        .data-table .model-name {
            font-weight: 500;
        }

        .data-table .provider {
            color: var(--text-muted);
            font-size: calc(var(--small-size) * 0.9);
        }

        .data-table .score {
            font-family: var(--font-mono);
            font-weight: 600;
            text-align: right;
            width: 4em;
        }

        .data-table .score-high {
            color: var(--accent-secondary);
            font-size: calc(var(--small-size) * 1.1);
        }

        .data-table tr.top-rank td {
            background: rgba(88, 166, 255, 0.08);
        }

        .data-table .bar-cell {
            width: 40%;
        }

        .score-bar {
            height: 6px;
            background: var(--bg-tertiary);
            border-radius: 3px;
            overflow: hidden;
        }

        .score-bar-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--accent), var(--accent-secondary));
            border-radius: 3px;
            transition: width 0.8s var(--ease-out-expo);
        }

        /* ===========================================
           SLIDE 3: SPEED
           =========================================== */
        .speed-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
            gap: var(--content-gap);
            max-width: 1100px;
        }

        .speed-card {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(1rem, 2vw, 1.5rem);
            display: flex;
            flex-direction: column;
            gap: 0.5em;
        }

        .speed-card .rank {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .speed-card .speed-value {
            font-family: var(--font-mono);
            font-size: clamp(1.8rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--accent-secondary);
        }

        .speed-card .speed-unit {
            font-size: calc(var(--small-size) * 0.9);
            color: var(--text-muted);
        }

        .speed-card .model-info {
            margin-top: 0.5em;
            padding-top: 0.5em;
            border-top: 1px solid var(--border);
        }

        .speed-card .model-name {
            font-weight: 600;
            font-size: var(--body-size);
        }

        .speed-card .provider {
            font-size: var(--small-size);
            color: var(--text-muted);
        }

        .speed-highlight {
            background: rgba(63, 185, 80, 0.1);
            border-color: var(--accent-secondary);
        }

        .speed-highlight .speed-value {
            color: var(--accent-secondary);
        }

        .insight-text {
            margin-top: var(--content-gap);
            padding: 1em 1.5em;
            background: var(--bg-secondary);
            border-left: 3px solid var(--accent);
            border-radius: 0 4px 4px 0;
            max-width: 800px;
        }

        .insight-text p {
            font-size: var(--body-size);
            color: var(--text-secondary);
        }

        .insight-text strong {
            color: var(--text-primary);
        }

        /* ===========================================
           SLIDE 4: PRICING
           =========================================== */
        .pricing-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
            max-width: 900px;
        }

        .pricing-item {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: clamp(0.8rem, 1.5vw, 1.2rem);
            display: flex;
            flex-direction: column;
            gap: 0.3em;
        }

        .pricing-item .model-name {
            font-weight: 500;
            font-size: var(--body-size);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .pricing-item .price {
            font-family: var(--font-mono);
            font-size: clamp(1.2rem, 2.5vw, 1.6rem);
            font-weight: 700;
        }

        .pricing-item .price-high {
            color: var(--accent-danger);
        }

        .pricing-item .price-low {
            color: var(--accent-secondary);
        }

        .pricing-item .price-mid {
            color: var(--accent-warning);
        }

        .pricing-item .rank {
            font-size: var(--small-size);
            color: var(--text-muted);
        }

        .pricing-range {
            display: flex;
            align-items: center;
            gap: 1em;
            margin-bottom: var(--content-gap);
            padding: 1em 1.5em;
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 6px;
            max-width: 600px;
        }

        .pricing-range .label {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .pricing-range .value {
            font-family: var(--font-mono);
            font-size: clamp(1.4rem, 3vw, 2rem);
            font-weight: 700;
        }

        .pricing-range .arrow {
            color: var(--text-muted);
            font-size: 1.5em;
        }

        .gap-badge {
            display: inline-block;
            padding: 0.5em 1em;
            background: rgba(248, 81, 73, 0.15);
            border: 1px solid var(--accent-danger);
            border-radius: 4px;
            color: var(--accent-danger);
            font-weight: 600;
            font-size: var(--body-size);
        }

        /* ===========================================
           SLIDE 5: TRADEOFFS
           =========================================== */
        .tradeoffs-layout {
            display: grid;
            grid-template-columns: 1.2fr 1fr;
            gap: var(--content-gap);
            max-width: 1200px;
            height: 100%;
            max-height: 75vh;
        }

        .scatter-container {
            display: flex;
            flex-direction: column;
            gap: 1em;
        }

        .scatter-image {
            max-height: min(55vh, 450px);
            width: 100%;
            object-fit: contain;
            border-radius: 8px;
            border: 1px solid var(--border);
        }

        .scatter-caption {
            font-size: var(--small-size);
            color: var(--text-muted);
            text-align: center;
        }

        .comparison-table {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 8px;
            overflow: hidden;
            font-size: var(--small-size);
        }

        .comparison-table caption {
            padding: 0.8em 1em;
            background: var(--bg-tertiary);
            text-align: left;
            font-weight: 600;
            border-bottom: 1px solid var(--border);
        }

        .comparison-table th {
