    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.totalSlides = this.slides.length;
                this.progressBar = document.getElementById('progressBar');
                this.navDots = document.getElementById('navDots');
                this.setupNavDots();
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupScrollNav();
                this.updateProgress();
            }

            setupNavDots() {
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(i));
                    this.navDots.appendChild(dot);
                });
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const index = parseInt(entry.target.dataset.slide);
                            this.currentSlide = index;
                            this.updateProgress();
                            this.updateNavDots();
                        }
                    });
                }, { threshold: 0.5 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.nextSlide();
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.prevSlide();
                    }
                });
            }

            setupScrollNav() {
                let isScrolling = false;
                window.addEventListener('wheel', (e) => {
                    if (isScrolling) return;
                    isScrolling = true;
                    setTimeout(() => isScrolling = false, 800);
                }, { passive: true });
            }

            goToSlide(index) {
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
            }

            nextSlide() {
                if (this.currentSlide < this.totalSlides - 1) {
                    this.goToSlide(this.currentSlide + 1);
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.goToSlide(this.currentSlide - 1);
                }
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.totalSlides) * 100;
                this.progressBar.style.width = progress + '%';
            }

            updateNavDots() {
                const dots = this.navDots.querySelectorAll('.nav-dot');
                dots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === this.currentSlide);
                });
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
            document.querySelectorAll('.slide').forEach(slide => slide.classList.add('visible'));
        });
    </script>
